namespace InventoryApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Hydraulic Press",      Location = "Building A, Bay 3",   LastInspected = new DateTime(2026, 6, 15) },
            new() { Id = 2, Name = "CNC Lathe",            Location = "Building B, Bay 1",   LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Welding Robot Arm",    Location = "Building A, Bay 7",   LastInspected = new DateTime(2026, 7, 1) },
            new() { Id = 4, Name = "Forklift #12",         Location = "Warehouse C",         LastInspected = new DateTime(2026, 4, 10) },
            new() { Id = 5, Name = "Overhead Crane",       Location = "Building D, Bay 2",   LastInspected = new DateTime(2026, 3, 30) },
            new() { Id = 6, Name = "Air Compressor Unit",  Location = "Utility Room 1",      LastInspected = new DateTime(2026, 6, 28) },
            new() { Id = 7, Name = "Band Saw",             Location = "Building B, Bay 4",   LastInspected = new DateTime(2026, 5, 5) },
            new() { Id = 8, Name = "Paint Spray Booth",    Location = "Building E",          LastInspected = new DateTime(2026, 2, 18) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Models
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    private const string PersistenceKey = "equipmentItems";

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistState);

        // If data was persisted during prerender, restore it instead of fetching again.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(PersistenceKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistState()
    {
        ApplicationState.PersistAsJson(PersistenceKey, _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

